#!/usr/bin/env bash
# SPDX-License-Identifier: MIT
# Copyright (c) 2026 the Tango authors
# build_ddr3_test.sh -- build the DDR3 bring-up test top (ddr3/test/tango_ddr3_test_top.v) for
# the Tang Console 138K; gate it (build_tools/sta_gate.py); archive it in <checkout>/bitstreams/ddr3_test/ (git-ignored)
# as tango_ddr3_test138_<YYYYMMDD-HHMM>_g<sha>.{fs,bin,txt}.  The DDR3 IP is generated by the build
# (ddr3/tango_ddr3_ip.tcl), never committed.  The .txt records the commit, whether the tree was clean, the sha256, the
# STA verdict and resources, and where the DDR3 PLL landed (PLL_L[0] wanted).
# Run from anywhere; memory-capped (build_tools/tango_capped.sh).  Never loads the board.
# TANGO_OUT: the build directory (default ddr3/test/out; one per concurrent build).  TANGO_PNR_OPTS: extra Gowin
# options, "name=value ..." (e.g. "replicate_resources=1 place_option=2"), recorded in the archive's name and .txt.
set -eu
cd "$(dirname "$0")/../.."
SYS="$(pwd)"
NAME=tango_ddr3_test138
OUT="${TANGO_OUT:-$SYS/ddr3/test/out}"
rm -rf "$OUT"; mkdir -p "$OUT"
BRD=$SYS/board/console138k
FILES="$SYS/ddr3/test/tango_ddr3_test_top.v $SYS/ddr3/test/tango_ddr3_test_core.v $SYS/ddr3/test/tango_ddr3_tester.v
       $SYS/ddr3/test/tango_ddr3_rmw.v $SYS/ddr3/test/tango_ddr3_ov.v $SYS/ddr3/test/tango_ddr3_uart.v
       $BRD/pll_init.v $BRD/pll_c27_mod.v $BRD/pll_c27.v $BRD/pll_c1485_mod.v $BRD/pll_c1485.v
       $BRD/pll_ddr3_mod.v $BRD/pll_ddr3.v $BRD/tango_tmds_ser.v $(ls $SYS/hdmi/*.sv)"
{
    echo "create_project -name $NAME -dir $OUT -pn GW5AST-LV138PG484AC1/I0 -device_version B -force"
    echo "source $SYS/ddr3/tango_ddr3_ip.tcl"
    echo "tango_ddr3_gen_ip $OUT/ip"
    for f in $FILES; do echo "add_file $f"; done
    echo "add_file $SYS/ddr3/test/tango_ddr3_test.cst"
    echo "add_file $SYS/ddr3/test/tango_ddr3_test.sdc"
    echo "set_option -top_module tango_ddr3_test_top"
    echo "set_option -verilog_std sysv2017"
    for o in ${TANGO_PNR_OPTS:-}; do echo "set_option -${o%%=*} ${o#*=}"; done
    echo "run syn"
    echo "run pnr"
} > "$OUT/build.tcl"
CAPPED=$SYS/build_tools/tango_capped.sh
export TANGO_MEM_CAP=${TANGO_MEM_CAP:-8G}
echo "build_ddr3_test: gw_sh $(date +%T) -> $OUT/build.log"
set +e
LD_LIBRARY_PATH="$HOME/gowin/IDE/lib" QT_QPA_PLATFORM=minimal LD_PRELOAD=/usr/lib/x86_64-linux-gnu/libfreetype.so.6 \
    timeout 3600 nice -n 10 "$CAPPED" "$HOME/gowin/IDE/bin/gw_sh" "$OUT/build.tcl" > "$OUT/build.log" 2>&1
RC=$?
set -e
PNR=$OUT/$NAME/impl/pnr
if [ $RC -ne 0 ] || [ ! -f "$PNR/$NAME.fs" ]; then
    grep -E 'ERROR|Error' "$OUT/build.log" | head -20
    echo "build_ddr3_test: BUILD FAILED (gw_sh exit $RC)"; exit 1
fi
set +e
python3 "$SYS/build_tools/sta_gate.py" "$PNR" > "$OUT/sta.txt" 2>&1
STA=$?
set -e
STAV=$([ $STA -eq 0 ] && echo PASS || echo FAIL)
# where the DDR3 PLL went: the 400 MHz clock's source site in the timing report
PLLSITE=$(grep -o -E 'PLL_[LRTB]\[[0-9]\][^<]{0,40}u_plld' "$PNR/${NAME}_tr_content.html" 2>/dev/null | head -1 | grep -o -E 'PLL_[LRTB]\[[0-9]\]' || true)
[ -n "$PLLSITE" ] || PLLSITE=$(python3 - "$PNR/${NAME}_tr_content.html" <<'PY'
import re, sys, html
s = re.sub(r'<[^>]+>', ' ', open(sys.argv[1], errors='replace').read()); s = html.unescape(s)
m = re.search(r'(PLL_[LRTB]\[\d\])\s+\S*u_plld\S*/CLKOUT2', s)
print(m.group(1) if m else 'unknown')
PY
)
SHA=$(git -C "$SYS" rev-parse --short=7 HEAD)
DIRTY=$(git -C "$SYS" status --porcelain --untracked-files=no | wc -l)
STAMP=$(date +%Y%m%d-%H%M)
ARC=$SYS/bitstreams/ddr3_test
mkdir -p "$ARC"
OPTT=$(echo "${TANGO_PNR_OPTS:-}" | tr -d ' _=' | tr -d 'a-z' | head -c 8)    # e.g. "12": the options' values
BASE=$ARC/${NAME}_${STAMP}_g${SHA}${OPTT:+_o$OPTT}
cp "$PNR/$NAME.fs" "$BASE.fs"
python3 "$SYS/build_tools/fs2bin.py" "$BASE.fs" "$BASE.bin" > /dev/null 2>&1 || cp "$PNR/$NAME.bin" "$BASE.bin" 2>/dev/null || true
chmod 444 "$BASE.fs" "$BASE.bin" 2>/dev/null || true
{
    echo "$NAME D1 DDR3 bring-up test (README \"The DDR3 path\"): sys-tango $SHA (uncommitted tracked files: $DIRTY), branch $(git -C "$SYS" branch --show-current)"
    echo "built $(date '+%F %T') with $(grep -m1 -o 'V1\.[0-9.]* Education' "$PNR/$NAME.rpt.txt" || echo 'the Gowin IDE')${TANGO_PNR_OPTS:+, options: $TANGO_PNR_OPTS}"
    echo "sha256 $(sha256sum "$BASE.fs" | cut -c1-64)  $(basename "$BASE.fs")"
    [ -f "$BASE.bin" ] && echo "sha256 $(sha256sum "$BASE.bin" | cut -c1-64)  $(basename "$BASE.bin")"
    echo "DDR3 PLL site: $PLLSITE (wanted PLL_L[0])"
    echo "STA GATE: $STAV"
    cat "$OUT/sta.txt"
    echo; echo "resources (PnR):"
    sed -n '/3. Resource Usage Summary/,/4. I\/O Bank Usage/p' "$PNR/$NAME.rpt.txt"
    echo "load: JTAG (SRAM); never flash.  Results: HDMI screen + U15 UART 115200."
} > "$BASE.txt"
echo "build_ddr3_test: $(basename "$BASE").fs STA $STAV, DDR3 PLL $PLLSITE"
cat "$BASE.txt" | head -12
[ $STA -eq 0 ]
